import React, { useState, useEffect } from 'react';
import Header from '../components/Header';
import Footer from '../components/Footer';
import { reportsAPI } from '../services/api';
import { toast } from 'react-toastify';
import { useAuth } from '../context/AuthContext';

const Reports = () => {
    const { store } = useAuth();

    // State for filters
    const [reportType, setReportType] = useState('date-range');
    const [startDate, setStartDate] = useState(
        new Date(Date.now() - 7 * 24 * 60 * 60 * 1000).toISOString().split('T')[0]
    );
    const [endDate, setEndDate] = useState(new Date().toISOString().split('T')[0]);
    const [selectedDate, setSelectedDate] = useState(new Date().toISOString().split('T')[0]);

    // State for data
    const [loading, setLoading] = useState(false);
    const [summary, setSummary] = useState({
        totalRevenue: 0,
        totalOrders: 0,
        totalItems: 0,
        avgOrderValue: 0,
        totalDiscount: 0,
        totalTax: 0,
    });
    const [dailyBreakdown, setDailyBreakdown] = useState([]);
    const [productData, setProductData] = useState([]);

    // Fetch reports
    const fetchReport = async (showToast = false) => {
        try {
            setLoading(true);

            const params = {
                storeId: store?.id || store?._id,
            };

            let reportData;
            let productsData;

            if (reportType === 'today') {
                params.date = selectedDate;
                const [reportResponse, productsResponse] = await Promise.all([
                    reportsAPI.getDailyReport(params),
                    reportsAPI.getProductRevenue({ ...params, startDate: selectedDate, endDate: selectedDate }),
                ]);
                reportData = reportResponse.data.data;
                productsData = productsResponse.data.data;

                setSummary(reportData.summary);
                setDailyBreakdown([]);
            } else if (reportType === 'date-range') {
                params.startDate = startDate;
                params.endDate = endDate;
                const [reportResponse, productsResponse] = await Promise.all([
                    reportsAPI.getDateRangeReport(params),
                    reportsAPI.getProductRevenue(params),
                ]);
                reportData = reportResponse.data.data;
                productsData = productsResponse.data.data;

                setSummary(reportData.summary);
                setDailyBreakdown(reportData.dailyBreakdown || []);
            }

            setProductData(productsData.products || []);
            if (showToast) {
                toast.success('Report generated successfully');
            }
        } catch (error) {
            console.error('Failed to fetch report:', error);
            toast.error('Failed to generate report');
        } finally {
            setLoading(false);
        }
    };

    // Download report as PDF
    const downloadPDF = () => {
        // Create PDF content
        const printWindow = window.open('', '_blank');
        const reportHTML = `
            <!DOCTYPE html>
            <html>
            <head>
                <title>Revenue Report - ${reportType === 'today' ? selectedDate : `${startDate} to ${endDate}`}</title>
                <style>
                    body { font-family: Arial, sans-serif; padding: 20px; }
                    h1 { color: #2563eb; margin-bottom: 10px; }
                    .meta { color: #666; margin-bottom: 30px; }
                    .summary { display: grid; grid-template-columns: repeat(4, 1fr); gap: 15px; margin-bottom: 30px; }
                    .card { border: 1px solid #ddd; border-radius: 8px; padding: 15px; }
                    .card h3 { margin: 0 0 10px 0; font-size: 14px; color: #666; }
                    .card .value { font-size: 24px; font-weight: bold; color: #333; }
                    table { width: 100%; border-collapse: collapse; margin-bottom: 30px; }
                    th, td { border: 1px solid #ddd; padding: 10px; text-align: left; }
                    th { background: #f3f4f6; font-weight: bold; }
                    .text-right { text-align: right; }
                    @media print { body { padding: 0; } }
                </style>
            </head>
            <body>
                <h1>Revenue Report</h1>
                <div class="meta">
                    <strong>Period:</strong> ${reportType === 'today' ? selectedDate : `${startDate} to ${endDate}`}<br>
                    <strong>Generated:</strong> ${new Date().toLocaleString('en-IN')}
                </div>

                <h2>Summary</h2>
                <div class="summary">
                    <div class="card">
                        <h3>Total Revenue</h3>
                        <div class="value">₹${summary.totalRevenue.toLocaleString('en-IN')}</div>
                    </div>
                    <div class="card">
                        <h3>Total Orders</h3>
                        <div class="value">${summary.totalOrders.toLocaleString('en-IN')}</div>
                    </div>
                    <div class="card">
                        <h3>Avg Order Value</h3>
                        <div class="value">₹${Math.round(summary.avgOrderValue).toLocaleString('en-IN')}</div>
                    </div>
                    <div class="card">
                        <h3>Items Sold</h3>
                        <div class="value">${summary.totalItems.toLocaleString('en-IN')}</div>
                    </div>
                </div>

                ${dailyBreakdown.length > 0 ? `
                    <h2>Day-wise Breakdown</h2>
                    <table>
                        <thead>
                            <tr>
                                <th>Date</th>
                                <th class="text-right">Orders</th>
                                <th class="text-right">Revenue</th>
                                <th class="text-right">Avg Order</th>
                            </tr>
                        </thead>
                        <tbody>
                            ${dailyBreakdown.map(row => `
                                <tr>
                                    <td>${new Date(row._id).toLocaleDateString('en-IN')}</td>
                                    <td class="text-right">${row.orders}</td>
                                    <td class="text-right">₹${row.revenue.toLocaleString('en-IN')}</td>
                                    <td class="text-right">₹${Math.round(row.avgOrderValue).toLocaleString('en-IN')}</td>
                                </tr>
                            `).join('')}
                        </tbody>
                    </table>
                ` : ''}

                ${productData.length > 0 ? `
                    <h2>Top Products by Revenue</h2>
                    <table>
                        <thead>
                            <tr>
                                <th>Product</th>
                                <th class="text-right">Qty Sold</th>
                                <th class="text-right">Revenue</th>
                                <th class="text-right">% of Total</th>
                            </tr>
                        </thead>
                        <tbody>
                            ${productData.slice(0, 10).map(product => `
                                <tr>
                                    <td>${product.itemName}</td>
                                    <td class="text-right">${product.quantitySold}</td>
                                    <td class="text-right">₹${product.totalRevenue.toLocaleString('en-IN')}</td>
                                    <td class="text-right">${product.percentage}%</td>
                                </tr>
                            `).join('')}
                        </tbody>
                    </table>
                ` : ''}
            </body>
            </html>
        `;

        printWindow.document.write(reportHTML);
        printWindow.document.close();
        printWindow.focus();

        setTimeout(() => {
            printWindow.print();
        }, 250);

        toast.success('PDF preview opened - use Print dialog to save as PDF');
    };

    // Load report on mount - without toast
    useEffect(() => {
        if (store?.id || store?._id) {
            fetchReport(false);
        }
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [store]);

    return (
        <div className="bg-background-light dark:bg-background-dark h-screen flex flex-col">
            <Header />

            <main className="flex-1 overflow-y-auto p-6">
                <div className="max-w-7xl mx-auto">
                    {/* Page Title */}
                    <div className="mb-6 flex items-center justify-between">
                        <div>
                            <h1 className="text-3xl font-bold text-slate-900 dark:text-slate-100 mb-2 flex items-center gap-3">
                                <span className="material-icons-round text-4xl text-primary">analytics</span>
                                Revenue Reports
                            </h1>
                            <p className="text-slate-500 dark:text-slate-400">
                                View your store's revenue and sales performance
                            </p>
                        </div>
                    </div>

                    {/* Filter Section */}
                    <div className="bg-white dark:bg-slate-900 rounded-2xl p-6 mb-6 border border-slate-200 dark:border-slate-800">
                        <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
                            <div>
                                <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-2">
                                    Report Type
                                </label>
                                <select
                                    value={reportType}
                                    onChange={(e) => setReportType(e.target.value)}
                                    className="w-full px-4 py-3 rounded-xl border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 text-slate-900 dark:text-slate-100 focus:outline-none focus:ring-2 focus:ring-primary"
                                >
                                    <option value="today">Today</option>
                                    <option value="date-range">Date Range</option>
                                </select>
                            </div>

                            {reportType === 'today' && (
                                <div>
                                    <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-2">
                                        Date
                                    </label>
                                    <input
                                        type="date"
                                        value={selectedDate}
                                        onChange={(e) => setSelectedDate(e.target.value)}
                                        className="w-full px-4 py-3 rounded-xl border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 text-slate-900 dark:text-slate-100 focus:outline-none focus:ring-2 focus:ring-primary"
                                    />
                                </div>
                            )}

                            {reportType === 'date-range' && (
                                <>
                                    <div>
                                        <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-2">
                                            Start Date
                                        </label>
                                        <input
                                            type="date"
                                            value={startDate}
                                            onChange={(e) => setStartDate(e.target.value)}
                                            className="w-full px-4 py-3 rounded-xl border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 text-slate-900 dark:text-slate-100 focus:outline-none focus:ring-2 focus:ring-primary"
                                        />
                                    </div>
                                    <div>
                                        <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-2">
                                            End Date
                                        </label>
                                        <input
                                            type="date"
                                            value={endDate}
                                            onChange={(e) => setEndDate(e.target.value)}
                                            className="w-full px-4 py-3 rounded-xl border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 text-slate-900 dark:text-slate-100 focus:outline-none focus:ring-2 focus:ring-primary"
                                        />
                                    </div>
                                </>
                            )}

                            <div className="flex items-end gap-2">
                                <button
                                    onClick={() => fetchReport(true)}
                                    disabled={loading}
                                    className="flex-1 bg-primary text-white px-6 py-3 rounded-xl font-semibold hover:bg-primary/90 disabled:opacity-50 disabled:cursor-not-allowed transition-colors flex items-center justify-center gap-2"
                                >
                                    {loading ? (
                                        <>
                                            <span className="material-icons-round animate-spin text-lg">
                                                refresh
                                            </span>
                                            Generating...
                                        </>
                                    ) : (
                                        <>
                                            <span className="material-icons-round text-lg">bar_chart</span>
                                            Generate
                                        </>
                                    )}
                                </button>
                                <button
                                    onClick={downloadPDF}
                                    disabled={loading || summary.totalRevenue === 0}
                                    className="px-6 py-3 rounded-xl font-semibold bg-green-600 text-white hover:bg-green-700 disabled:opacity-50 disabled:cursor-not-allowed transition-colors flex items-center justify-center gap-2"
                                    title="Download as PDF"
                                >
                                    <span className="material-icons-round text-lg">picture_as_pdf</span>
                                    PDF
                                </button>
                            </div>
                        </div>
                    </div>

                    {/* Summary Cards */}
                    <div className="grid grid-cols-1 md:grid-cols-4 gap-4 mb-6">
                        <div className="bg-gradient-to-br from-green-500 to-green-600 text-white rounded-2xl p-6 shadow-lg transform hover:scale-105 transition-transform">
                            <div className="flex items-center justify-between mb-2">
                                <span className="text-sm font-medium opacity-90">Total Revenue</span>
                                <div className="w-12 h-12 bg-white/20 rounded-xl flex items-center justify-center">
                                    <span className="material-icons-round text-2xl">
                                        attach_money
                                    </span>
                                </div>
                            </div>
                            <div className="text-3xl font-bold mb-1">
                                ₹{summary.totalRevenue.toLocaleString('en-IN')}
                            </div>
                            <div className="text-xs opacity-75">
                                Revenue generated in period
                            </div>
                        </div>

                        <div className="bg-gradient-to-br from-blue-500 to-blue-600 text-white rounded-2xl p-6 shadow-lg transform hover:scale-105 transition-transform">
                            <div className="flex items-center justify-between mb-2">
                                <span className="text-sm font-medium opacity-90">Total Orders</span>
                                <div className="w-12 h-12 bg-white/20 rounded-xl flex items-center justify-center">
                                    <span className="material-icons-round text-2xl">
                                        shopping_cart
                                    </span>
                                </div>
                            </div>
                            <div className="text-3xl font-bold mb-1">
                                {summary.totalOrders.toLocaleString('en-IN')}
                            </div>
                            <div className="text-xs opacity-75">
                                Orders completed
                            </div>
                        </div>

                        <div className="bg-gradient-to-br from-yellow-500 to-yellow-600 text-white rounded-2xl p-6 shadow-lg transform hover:scale-105 transition-transform">
                            <div className="flex items-center justify-between mb-2">
                                <span className="text-sm font-medium opacity-90">Avg Order Value</span>
                                <div className="w-12 h-12 bg-white/20 rounded-xl flex items-center justify-center">
                                    <span className="material-icons-round text-2xl">
                                        receipt
                                    </span>
                                </div>
                            </div>
                            <div className="text-3xl font-bold mb-1">
                                ₹{Math.round(summary.avgOrderValue).toLocaleString('en-IN')}
                            </div>
                            <div className="text-xs opacity-75">
                                Per order average
                            </div>
                        </div>

                        <div className="bg-gradient-to-br from-purple-500 to-purple-600 text-white rounded-2xl p-6 shadow-lg transform hover:scale-105 transition-transform">
                            <div className="flex items-center justify-between mb-2">
                                <span className="text-sm font-medium opacity-90">Items Sold</span>
                                <div className="w-12 h-12 bg-white/20 rounded-xl flex items-center justify-center">
                                    <span className="material-icons-round text-2xl">
                                        inventory_2
                                    </span>
                                </div>
                            </div>
                            <div className="text-3xl font-bold mb-1">
                                {summary.totalItems.toLocaleString('en-IN')}
                            </div>
                            <div className="text-xs opacity-75">
                                Total items sold
                            </div>
                        </div>
                    </div>

                    {/* Day-wise Breakdown Table (for date range) */}
                    {dailyBreakdown.length > 0 && (
                        <div className="bg-white dark:bg-slate-900 rounded-2xl p-6 mb-6 border border-slate-200 dark:border-slate-800 shadow-sm">
                            <h2 className="text-xl font-bold text-slate-900 dark:text-slate-100 mb-4 flex items-center gap-2">
                                <span className="material-icons-round text-primary">calendar_today</span>
                                Day-wise Breakdown
                            </h2>
                            <div className="overflow-x-auto">
                                <table className="w-full">
                                    <thead>
                                        <tr className="border-b border-slate-200 dark:border-slate-800">
                                            <th className="text-left py-3 px-4 text-sm font-semibold text-slate-700 dark:text-slate-300">
                                                Date
                                            </th>
                                            <th className="text-right py-3 px-4 text-sm font-semibold text-slate-700 dark:text-slate-300">
                                                Orders
                                            </th>
                                            <th className="text-right py-3 px-4 text-sm font-semibold text-slate-700 dark:text-slate-300">
                                                Revenue
                                            </th>
                                            <th className="text-right py-3 px-4 text-sm font-semibold text-slate-700 dark:text-slate-300">
                                                Avg Order
                                            </th>
                                        </tr>
                                    </thead>
                                    <tbody>
                                        {dailyBreakdown.map((row, index) => (
                                            <tr
                                                key={index}
                                                className="border-b border-slate-100 dark:border-slate-800 hover:bg-slate-50 dark:hover:bg-slate-800 transition-colors"
                                            >
                                                <td className="py-3 px-4 text-sm text-slate-900 dark:text-slate-100">
                                                    {new Date(row._id).toLocaleDateString('en-IN', {
                                                        weekday: 'short',
                                                        day: '2-digit',
                                                        month: 'short',
                                                        year: 'numeric',
                                                    })}
                                                </td>
                                                <td className="py-3 px-4 text-sm text-right text-slate-900 dark:text-slate-100">
                                                    {row.orders}
                                                </td>
                                                <td className="py-3 px-4 text-sm text-right text-slate-900 dark:text-slate-100 font-semibold">
                                                    ₹{row.revenue.toLocaleString('en-IN')}
                                                </td>
                                                <td className="py-3 px-4 text-sm text-right text-slate-900 dark:text-slate-100">
                                                    ₹{Math.round(row.avgOrderValue).toLocaleString('en-IN')}
                                                </td>
                                            </tr>
                                        ))}
                                    </tbody>
                                </table>
                            </div>
                        </div>
                    )}

                    {/* Top Products Table */}
                    {productData.length > 0 && (
                        <div className="bg-white dark:bg-slate-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm">
                            <h2 className="text-xl font-bold text-slate-900 dark:text-slate-100 mb-4 flex items-center gap-2">
                                <span className="material-icons-round text-primary">stars</span>
                                Top Products by Revenue
                            </h2>
                            <div className="overflow-x-auto">
                                <table className="w-full">
                                    <thead>
                                        <tr className="border-b border-slate-200 dark:border-slate-800">
                                            <th className="text-left py-3 px-4 text-sm font-semibold text-slate-700 dark:text-slate-300">
                                                Product
                                            </th>
                                            <th className="text-right py-3 px-4 text-sm font-semibold text-slate-700 dark:text-slate-300">
                                                Qty Sold
                                            </th>
                                            <th className="text-right py-3 px-4 text-sm font-semibold text-slate-700 dark:text-slate-300">
                                                Revenue
                                            </th>
                                            <th className="text-right py-3 px-4 text-sm font-semibold text-slate-700 dark:text-slate-300">
                                                % of Total
                                            </th>
                                        </tr>
                                    </thead>
                                    <tbody>
                                        {productData.slice(0, 10).map((product, index) => (
                                            <tr
                                                key={index}
                                                className="border-b border-slate-100 dark:border-slate-800 hover:bg-slate-50 dark:hover:bg-slate-800 transition-colors"
                                            >
                                                <td className="py-3 px-4 text-sm text-slate-900 dark:text-slate-100">
                                                    {product.itemName}
                                                </td>
                                                <td className="py-3 px-4 text-sm text-right text-slate-900 dark:text-slate-100">
                                                    {product.quantitySold}
                                                </td>
                                                <td className="py-3 px-4 text-sm text-right text-slate-900 dark:text-slate-100 font-semibold">
                                                    ₹{product.totalRevenue.toLocaleString('en-IN')}
                                                </td>
                                                <td className="py-3 px-4 text-sm text-right text-slate-900 dark:text-slate-100">
                                                    {product.percentage}%
                                                </td>
                                            </tr>
                                        ))}
                                    </tbody>
                                </table>
                            </div>
                        </div>
                    )}
                </div>
            </main>

            <Footer />
        </div>
    );
};

export default Reports;
