import React, { useState, useEffect, useCallback, useMemo } from 'react';
import Header from '../components/Header';
import Footer from '../components/Footer';
import CategorySidebar from '../components/CategorySidebar';
import FoodItemCard from '../components/FoodItemCard';
import CartPanel from '../components/CartPanel';
import { categoriesAPI, storeMenuAPI } from '../services/api';
import { useCart } from '../context/CartContext';
import { useAuth } from '../context/AuthContext';
import { getCache, setCache } from '../utils/cache';
import { useDebounce } from '../hooks/useDebounce';

const POSHome = () => {
    const [categories, setCategories] = useState([]);
    const [selectedCategory, setSelectedCategory] = useState(null);
    const [foodItems, setFoodItems] = useState([]);
    const [allStoreItems, setAllStoreItems] = useState([]); // Cache all store items
    const [loading, setLoading] = useState(true);
    const [searchQuery, setSearchQuery] = useState('');
    const { addToCart } = useCart();
    const { store } = useAuth();

    const storeId = store?.id || store?._id;

    // Memoize icon mapping function with more unique icons
    const getCategoryIcon = useCallback((categoryName) => {
        const iconMap = {
            'Beverages': 'local_cafe',
            'Main Course': 'restaurant',
            'Snacks': 'fastfood',
            'Desserts': 'bakery_dining',
            'Burgers': 'lunch_dining',
            'Pizzas': 'local_pizza',
            'Waffles': 'icecream',
            'Cakes': 'cake',
            'Bakery': 'bakery_dining',
            'Cold Drinks': 'local_bar',
            'Ice Cream & Family Pack': 'icecream',
            'Sweets': 'cookie',
            'Masalas & Spices': 'spa',
            'Mukhwas': 'emoji_nature',
            'Pickles & Chutney': 'emoji_food_beverage',
            'Ready to Cook & Eat': 'ramen_dining',
            'Seasonable Products': 'eco',
            'Biscuits & Cookies': 'cookie',
            'Farari': 'rice_bowl',
            'Noodle & Pasta': 'ramen_dining',
            'Snacks & Namkeens': 'fastfood',
            'Spreads & Ketchup': 'kitchen',
            'Chocolates & Candies': 'candy',
            'Garam Items': 'local_fire_department',
            'Hoodies': 'checkroom',
            'Merchandise': 'storefront',
            'Favorites': 'star',
        };
        // Try to match by exact name, then by lowercase, then fallback
        return (
            iconMap[categoryName] ||
            iconMap[categoryName?.trim()] ||
            iconMap[categoryName?.toLowerCase()] ||
            'category'
        );
    }, []);

    // Fetch store menu - NO CACHING for instant updates
    const fetchStoreMenu = useCallback(async (sid) => {
        if (!sid) return;

        try {
            console.log('Fetching store menu from API (no cache)');
            const response = await storeMenuAPI.getMenu(sid);
            if (response.data.isOk) {
                const items = response.data.data.items;
                setAllStoreItems(items);
            }
        } catch (error) {
            console.error('Error fetching store menu:', error);
            setAllStoreItems([]);
        }
    }, []);

    // Fetch categories - NO CACHING for instant updates
    const fetchCategories = useCallback(async () => {
        try {
            setLoading(true);
            console.log('Fetching categories from API (no cache)');
            const response = await categoriesAPI.getAll();
            if (response.data.isOk) {
                // Add Favorites as first category
                const favoritesCategory = {
                    _id: 'favorites',
                    categoryName: 'Favorites',
                    icon: 'star'
                };
                // Map categories to include icon names
                const categoriesWithIcons = response.data.data.map(cat => ({
                    ...cat,
                    icon: getCategoryIcon(cat.categoryName)
                }));
                const allCategories = [favoritesCategory, ...categoriesWithIcons];
                setCategories(allCategories);
                if (allCategories.length > 0 && !selectedCategory) {
                    setSelectedCategory(allCategories[0]);
                }
            }
        } catch (error) {
            console.error('Error fetching categories:', error);
            setCategories([]);
        } finally {
            setLoading(false);
        }
    }, [getCategoryIcon, selectedCategory]);

    // Filter items by category - memoized with useCallback
    const filterItemsByCategory = useCallback((categoryId) => {
        try {
            if (categoryId === 'favorites') {
                // Filter items with isFavorite = true
                const favoriteItems = allStoreItems.filter(item => item.isFavorite === true);
                setFoodItems(favoriteItems);
            } else {
                // Filter items by category
                const categoryItems = allStoreItems.filter(
                    item => item.categoryId?._id === categoryId || item.categoryId === categoryId
                );
                setFoodItems(categoryItems);
            }
        } catch (error) {
            console.error('Error filtering items:', error);
            setFoodItems([]);
        }
    }, [allStoreItems]);

    // Refresh data manually
    const handleRefresh = useCallback(() => {
        if (storeId) {
            fetchCategories();
            fetchStoreMenu(storeId);
        }
    }, [storeId, fetchCategories, fetchStoreMenu]);

    // Initial data load (only run once when storeId is available)
    useEffect(() => {
        if (storeId) {
            fetchCategories();
            fetchStoreMenu(storeId);
        }
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [storeId]); // Only depend on storeId, not the functions

    // Auto-refresh on window focus (to catch newly added items)
    useEffect(() => {
        const handleFocus = () => {
            console.log('Window focused - refreshing data');
            handleRefresh();
        };

        window.addEventListener('focus', handleFocus);

        return () => {
            window.removeEventListener('focus', handleFocus);
        };
    }, [handleRefresh]);

    // Auto-refresh every 30 seconds for real-time updates
    useEffect(() => {
        if (!storeId) return;

        const interval = setInterval(() => {
            console.log('Auto-refreshing data (30s interval)');
            fetchStoreMenu(storeId);
            // Don't refresh categories as they change less frequently
        }, 30000); // 30 seconds

        return () => clearInterval(interval);
    }, [storeId, fetchStoreMenu]);

    // Filter items when category or store items change
    useEffect(() => {
        if (selectedCategory && allStoreItems.length > 0) {
            filterItemsByCategory(selectedCategory._id);
        } else if (selectedCategory && allStoreItems.length === 0) {
            // No items available for this store
            setFoodItems([]);
        }
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [selectedCategory, allStoreItems]); // Don't include filterItemsByCategory as dependency

    // Memoize add to cart handler
    const handleAddToCart = useCallback((item) => {
        addToCart(item);
    }, [addToCart]);

    // Debounce search query to reduce filtering operations
    const debouncedSearchQuery = useDebounce(searchQuery, 300);

    // Memoize filtered items based on debounced search query for better performance
    const filteredItems = useMemo(() => {
        if (!debouncedSearchQuery.trim()) return foodItems;
        const lowerQuery = debouncedSearchQuery.toLowerCase();
        return foodItems.filter(item =>
            item.itemName.toLowerCase().includes(lowerQuery) ||
            item.itemCode.toLowerCase().includes(lowerQuery)
        );
    }, [foodItems, debouncedSearchQuery]);

    return (
        <div className="bg-background-light dark:bg-background-dark text-slate-900 dark:text-slate-100 h-screen overflow-hidden flex flex-col">
            <Header />
            
            <main className="flex-1 flex overflow-hidden">
                <CategorySidebar
                    categories={categories}
                    selectedCategory={selectedCategory}
                    onSelectCategory={setSelectedCategory}
                />

                <section className="flex-1 bg-background-light dark:bg-background-dark p-6 flex flex-col gap-6 overflow-y-auto">
                    <div className="flex flex-col sm:flex-row gap-4">
                        <div className="relative flex-1">
                            <span className="material-icons-round absolute left-4 top-1/2 -translate-y-1/2 text-slate-400">
                                search
                            </span>
                            <input
                                className="w-full pl-12 pr-4 py-3 rounded-2xl border-none ring-1 ring-slate-200 dark:ring-slate-700 bg-white dark:bg-slate-900 focus:ring-2 focus:ring-primary shadow-sm outline-none transition-all"
                                placeholder="Search for items, categories or codes..."
                                type="text"
                                value={searchQuery}
                                onChange={(e) => setSearchQuery(e.target.value)}
                            />
                        </div>
                        <button
                            onClick={handleRefresh}
                            className="px-4 py-3 rounded-2xl bg-white dark:bg-slate-900 ring-1 ring-slate-200 dark:ring-slate-700 hover:ring-2 hover:ring-primary shadow-sm transition-all flex items-center gap-2"
                            title="Refresh products"
                        >
                            <span className="material-icons-round text-primary">refresh</span>
                            <span className="text-sm font-medium text-slate-700 dark:text-slate-300 hidden sm:inline">Refresh</span>
                        </button>
                    </div>

                    {loading ? (
                        <div className="flex-1 flex items-center justify-center">
                            <div className="text-center">
                                <div className="w-12 h-12 border-4 border-primary border-t-transparent rounded-full animate-spin mx-auto mb-4"></div>
                                <p className="text-slate-600">Loading items...</p>
                            </div>
                        </div>
                    ) : (
                        <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-4 xl:grid-cols-5 gap-3">
                            {filteredItems.map((item) => (
                                <FoodItemCard
                                    key={item._id}
                                    item={item}
                                    onAddToCart={handleAddToCart}
                                />
                            ))}
                        </div>
                    )}
                </section>

                <CartPanel />
            </main>

            <Footer />
        </div>
    );
};

export default POSHome;
