import React, { useState, useEffect } from 'react';
import Header from '../components/Header';
import Footer from '../components/Footer';
import { format } from 'date-fns';
import { billsAPI, kotAPI } from '../services/api';

const BillsKOT = () => {
    const [activeTab, setActiveTab] = useState('bills'); // 'bills' or 'kot'
    const [selectedDate, setSelectedDate] = useState(new Date());
    const [bills, setBills] = useState([]);
    const [kots, setKots] = useState([]);
    const [loading, setLoading] = useState(false);

    useEffect(() => {
        if (activeTab === 'bills') {
            fetchBills();
        } else {
            fetchKOTs();
        }
    }, [activeTab, selectedDate]);

    const fetchBills = async () => {
        try {
            setLoading(true);
            const dateStr = format(selectedDate, 'yyyy-MM-dd');
            console.log('Fetching bills for date:', dateStr, 'Selected date object:', selectedDate);
            const response = await billsAPI.getByDate(dateStr);
            console.log('Bills API response:', response.data);
            if (response.data.isOk) {
                setBills(response.data.data || []);
                console.log('Bills found:', response.data.data?.length || 0);
            } else {
                setBills([]);
                console.log('No bills returned or isOk is false');
            }
        } catch (error) {
            console.error('Error fetching bills:', error);
            setBills([]);
        } finally {
            setLoading(false);
        }
    };

    const fetchKOTs = async () => {
        try {
            setLoading(true);
            const dateStr = format(selectedDate, 'yyyy-MM-dd');
            console.log('Fetching KOTs for date:', dateStr, 'Selected date object:', selectedDate);
            const response = await kotAPI.getByDate(dateStr);
            console.log('KOT API response:', response.data);
            if (response.data.isOk) {
                setKots(response.data.data || []);
                console.log('KOTs found:', response.data.data?.length || 0);
            } else {
                setKots([]);
                console.log('No KOTs returned or isOk is false');
            }
        } catch (error) {
            console.error('Error fetching KOTs:', error);
            setKots([]);
        } finally {
            setLoading(false);
        }
    };

    const handlePrint = async (id) => {
        try {
            if (activeTab === 'bills') {
                await billsAPI.print(id);
            } else {
                await kotAPI.print(id);
            }
            // You can add a print dialog or open a new window with the print view if needed
        } catch (error) {
            console.error('Error printing:', error);
        }
    };

    return (
        <div className="bg-background-light dark:bg-background-dark text-slate-900 dark:text-slate-100 h-screen overflow-hidden flex flex-col">
            <Header />
            
            <main className="flex-1 flex flex-col overflow-hidden p-6">
                {/* Page Header */}
                <div className="mb-6">
                    <h1 className="text-3xl font-bold text-slate-900 dark:text-slate-100 mb-2">
                        Bills &amp; KOT Management
                    </h1>
                    <p className="text-slate-500 dark:text-slate-400">
                        View and manage your daily bills and kitchen orders
                    </p>
                </div>

                {/* Tabs and Date Filter */}
                <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 mb-6">
                    <div className="flex bg-white dark:bg-slate-900 rounded-xl p-1 border border-slate-200 dark:border-slate-800">
                        <button
                            onClick={() => setActiveTab('bills')}
                            className={`px-6 py-2 rounded-lg font-semibold text-sm transition-all ${
                                activeTab === 'bills'
                                    ? 'bg-primary text-white shadow-md'
                                    : 'text-slate-500 hover:text-slate-700'
                            }`}
                        >
                            Bills
                        </button>
                        <button
                            onClick={() => setActiveTab('kot')}
                            className={`px-6 py-2 rounded-lg font-semibold text-sm transition-all ${
                                activeTab === 'kot'
                                    ? 'bg-primary text-white shadow-md'
                                    : 'text-slate-500 hover:text-slate-700'
                            }`}
                        >
                            KOT
                        </button>
                    </div>

                    <div className="flex items-center gap-2">
                        <span className="material-icons-round text-slate-400">calendar_today</span>
                        <input
                            type="date"
                            value={format(selectedDate, 'yyyy-MM-dd')}
                            onChange={(e) => setSelectedDate(new Date(e.target.value))}
                            className="px-4 py-2 rounded-xl border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-900 text-slate-900 dark:text-slate-100 outline-none focus:ring-2 focus:ring-primary"
                        />
                    </div>
                </div>

                {/* Content */}
                <div className="flex-1 overflow-hidden bg-white dark:bg-slate-900 rounded-2xl border border-slate-200 dark:border-slate-800 p-6">
                    {loading ? (
                        <div className="h-full flex items-center justify-center">
                            <div className="text-center">
                                <div className="w-12 h-12 border-4 border-primary border-t-transparent rounded-full animate-spin mx-auto mb-4"></div>
                                <p className="text-slate-600">Loading...</p>
                            </div>
                        </div>
                    ) : (
                        <div className="h-full overflow-y-auto">
                            {activeTab === 'bills' ? (
                                <div className="space-y-3">
                                    {bills.length === 0 ? (
                                        <div className="text-center py-12">
                                            <span className="material-icons-round text-6xl text-slate-300 mb-4">
                                                receipt_long
                                            </span>
                                            <p className="text-slate-500">No bills found for selected date</p>
                                        </div>
                                    ) : (
                                        bills.map((bill) => (
                                            <div
                                                key={bill._id}
                                                className="flex items-center justify-between p-4 bg-slate-50 dark:bg-slate-800 rounded-xl hover:shadow-md transition-all"
                                            >
                                                <div className="flex items-center gap-4">
                                                    <div className="w-12 h-12 rounded-full bg-primary/10 flex items-center justify-center">
                                                        <span className="material-icons-round text-primary">
                                                            receipt
                                                        </span>
                                                    </div>
                                                    <div>
                                                        <h3 className="font-bold text-lg">
                                                            {bill.billNumber}
                                                        </h3>
                                                        <p className="text-sm text-slate-500">
                                                            Order #{bill.orderNumber} • {bill.time}
                                                        </p>
                                                    </div>
                                                </div>
                                                <div className="flex items-center gap-6">
                                                    <div className="text-right">
                                                        <p className="text-2xl font-bold text-primary">
                                                            ₹{bill.total.toFixed(2)}
                                                        </p>
                                                        <p className="text-xs text-slate-500">
                                                            {bill.items} items • {bill.orderType}
                                                        </p>
                                                    </div>
                                                    <button
                                                        onClick={() => handlePrint(bill._id)}
                                                        className="p-3 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-xl hover:bg-primary hover:text-white hover:border-primary transition-all"
                                                    >
                                                        <span className="material-icons-round">print</span>
                                                    </button>
                                                </div>
                                            </div>
                                        ))
                                    )}
                                </div>
                            ) : (
                                <div className="space-y-3">
                                    {kots.length === 0 ? (
                                        <div className="text-center py-12">
                                            <span className="material-icons-round text-6xl text-slate-300 mb-4">
                                                restaurant
                                            </span>
                                            <p className="text-slate-500">No KOTs found for selected date</p>
                                        </div>
                                    ) : (
                                        kots.map((kot) => (
                                            <div
                                                key={kot._id}
                                                className="flex items-center justify-between p-4 bg-slate-50 dark:bg-slate-800 rounded-xl hover:shadow-md transition-all"
                                            >
                                                <div className="flex items-center gap-4">
                                                    <div className="w-12 h-12 rounded-full bg-orange-500/10 flex items-center justify-center">
                                                        <span className="material-icons-round text-orange-500">
                                                            restaurant_menu
                                                        </span>
                                                    </div>
                                                    <div>
                                                        <h3 className="font-bold text-lg">
                                                            {kot.kotNumber}
                                                        </h3>
                                                        <p className="text-sm text-slate-500">
                                                            Order #{kot.orderNumber} • {kot.time}
                                                        </p>
                                                    </div>
                                                </div>
                                                <div className="flex items-center gap-6">
                                                    <div className="text-right">
                                                        <span
                                                            className={`px-3 py-1 rounded-full text-xs font-bold ${
                                                                kot.status === 'prepared'
                                                                    ? 'bg-green-100 text-green-600'
                                                                    : 'bg-yellow-100 text-yellow-600'
                                                            }`}
                                                        >
                                                            {kot.status.toUpperCase()}
                                                        </span>
                                                        <p className="text-xs text-slate-500 mt-1">
                                                            {kot.items} items • {kot.orderType}
                                                        </p>
                                                    </div>
                                                    <button
                                                        onClick={() => handlePrint(kot._id)}
                                                        className="p-3 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-xl hover:bg-orange-500 hover:text-white hover:border-orange-500 transition-all"
                                                    >
                                                        <span className="material-icons-round">print</span>
                                                    </button>
                                                </div>
                                            </div>
                                        ))
                                    )}
                                </div>
                            )}
                        </div>
                    )}
                </div>
            </main>

            <Footer />
        </div>
    );
};

export default BillsKOT;
