import React, { useState } from 'react';
import { useAuth } from '../context/AuthContext';
import { useNavigate } from 'react-router-dom';

const Header = () => {
    const { user, store, logout } = useAuth();
    const [showDropdown, setShowDropdown] = useState(false);
    const navigate = useNavigate();

    const handleLogout = () => {
        logout();
        navigate('/login');
    };

    return (
        <header className="h-16 border-b border-slate-200 dark:border-slate-800 bg-white dark:bg-slate-900 px-4 flex items-center justify-between shrink-0">
            <div className="flex items-center gap-4">
                <img
                    alt="Bhakti Logo"
                    className="h-10 cursor-pointer"
                    src={`${process.env.PUBLIC_URL}/logo.png`}
                    onClick={() => navigate('/')}
                />
                <div className="h-8 w-px bg-slate-200 dark:bg-slate-700 mx-2"></div>
                <div className="flex items-center gap-2 bg-slate-100 dark:bg-slate-800 px-3 py-1.5 rounded-lg">
                    <span className="material-icons-round text-primary text-sm">store</span>
                    <span className="text-sm font-medium">
                        {store?.name || 'Store'} - {store?.counter || 'Counter 1'}
                    </span>
                </div>
            </div>
            <div className="flex items-center gap-6">
                <div className="hidden md:flex items-center gap-2 text-slate-500">
                    <span className="material-icons-round text-sm">phone_in_talk</span>
                    <span className="text-sm font-semibold text-slate-700 dark:text-slate-300">
                        9099912483
                    </span>
                </div>
                <div className="flex items-center gap-3">
                    <button
                        onClick={() => navigate('/bills-kot')}
                        className="p-2 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-full transition-colors"
                        title="Bills & KOT"
                    >
                        <span className="material-icons-round">receipt_long</span>
                    </button>
                    <button
                        onClick={() => navigate('/items')}
                        className="p-2 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-full transition-colors"
                        title="Manage Items"
                    >
                        <span className="material-icons-round">inventory_2</span>
                    </button>
                    <button
                        onClick={() => navigate('/reports')}
                        className="p-2 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-full transition-colors"
                        title="Reports"
                    >
                        <span className="material-icons-round">bar_chart</span>
                    </button>
                    <div className="relative">
                        <div
                            className="flex items-center gap-2 ml-2 cursor-pointer"
                            onClick={() => setShowDropdown(!showDropdown)}
                        >
                            <div className="w-8 h-8 rounded-full bg-primary flex items-center justify-center text-white text-xs font-bold">
                                {user?.name?.charAt(0) || 'U'}
                            </div>
                            <span className="text-sm font-medium hidden sm:block">
                                {user?.name || 'User'}
                            </span>
                        </div>
                        {showDropdown && (
                            <div className="absolute right-0 mt-2 w-48 bg-white dark:bg-slate-800 rounded-xl shadow-lg border border-slate-200 dark:border-slate-700 py-2 z-50">
                                <button
                                    onClick={handleLogout}
                                    className="w-full px-4 py-2 text-left text-sm hover:bg-slate-100 dark:hover:bg-slate-700 flex items-center gap-2"
                                >
                                    <span className="material-icons-round text-sm">logout</span>
                                    Logout
                                </button>
                            </div>
                        )}
                    </div>
                </div>
            </div>
        </header>
    );
};

export default Header;
