import React, { createContext, useState, useContext, useEffect, useCallback, useMemo } from 'react';
import { authAPI } from '../services/api';
import { toast } from 'react-toastify';

const AuthContext = createContext();

export const useAuth = () => {
    const context = useContext(AuthContext);
    if (!context) {
        throw new Error('useAuth must be used within AuthProvider');
    }
    return context;
};

export const AuthProvider = ({ children }) => {
    const [user, setUser] = useState(null);
    const [store, setStore] = useState(null);
    const [loading, setLoading] = useState(true);
    const [isAuthenticated, setIsAuthenticated] = useState(false);

    useEffect(() => {
        // Check if user is already logged in
        const storedUser = localStorage.getItem('pos_user');
        const storedStore = localStorage.getItem('pos_store');
        const token = localStorage.getItem('pos_token');

        if (storedUser && storedStore && token) {
            setUser(JSON.parse(storedUser));
            setStore(JSON.parse(storedStore));
            setIsAuthenticated(true);
        }
        setLoading(false);
    }, []);

    const login = useCallback(async (storeCode) => {
        try {
            setLoading(true);
            const response = await authAPI.login({ storeCode });
            
            if (response.data.isOk) {
                setUser(response.data.data.user);
                setStore(response.data.data.store);
                setIsAuthenticated(true);

                localStorage.setItem('pos_user', JSON.stringify(response.data.data.user));
                localStorage.setItem('pos_store', JSON.stringify(response.data.data.store));
                localStorage.setItem('pos_token', response.data.token);

                toast.success('Login successful!');
                return { success: true };
            } else {
                toast.error(response.data.message || 'Login failed');
                return { success: false, error: response.data.message };
            }
        } catch (error) {
            toast.error(error.response?.data?.message || 'Login failed');
            return { success: false, error: error.message };
        } finally {
            setLoading(false);
        }
    }, []);

    const logout = useCallback(() => {
        setUser(null);
        setStore(null);
        setIsAuthenticated(false);
        localStorage.removeItem('pos_user');
        localStorage.removeItem('pos_store');
        localStorage.removeItem('pos_token');
        toast.info('Logged out successfully');
    }, []);

    const value = useMemo(() => ({
        user,
        store,
        loading,
        isAuthenticated,
        login,
        logout
    }), [user, store, loading, isAuthenticated, login, logout]);

    return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
};
