import axios from 'axios';

const API_URL = process.env.REACT_APP_API_URL || 'http://localhost:7005/api/v1';
const BASE_URL = process.env.REACT_APP_API_URL ? process.env.REACT_APP_API_URL.replace('/api/v1', '') : 'http://localhost:7005';

// Create axios instance
const api = axios.create({
    baseURL: API_URL,
    headers: {
        'Content-Type': 'application/json',
    },
});

// Add token to requests
api.interceptors.request.use(
    (config) => {
        const token = localStorage.getItem('pos_token');
        if (token) {
            config.headers.Authorization = `Bearer ${token}`;
        }
        return config;
    },
    (error) => {
        return Promise.reject(error);
    }
);

// Auth API
export const authAPI = {
    login: (data) => api.post('/pos/login', data),
    logout: () => api.post('/auth/logout'),
};

// Categories API
export const categoriesAPI = {
    getAll: () => api.get('/categories').then(res => {
        // Add full URL to image paths
        if (res.data.isOk && res.data.data) {
            const baseUrl = BASE_URL;
            res.data.data = res.data.data.map(category => ({
                ...category,
                image: category.imageUrl ? `${baseUrl}/${category.imageUrl.replace(/\\/g, '/')}` : null
            }));
        }
        return res;
    }),
    getById: (id) => api.get(`/categories/${id}`),
};

// Food Items API
export const foodItemsAPI = {
    getAll: (params) => api.get('/food-items', { params }).then(res => {
        // Transform imageUrl to image for consistency and add full URL
        if (res.data.isOk && res.data.data) {
            const baseUrl = BASE_URL;
            res.data.data = res.data.data.map(item => ({
                ...item,
                image: item.imageUrl ? `${baseUrl}/${item.imageUrl.replace(/\\/g, '/')}` : null
            }));
        }
        return res;
    }),
    getByCategory: (categoryId) => api.get(`/food-items`, { params: { categoryId } }).then(res => {
        if (res.data.isOk && res.data.data) {
            const baseUrl = BASE_URL;
            res.data.data = res.data.data.map(item => ({
                ...item,
                image: item.imageUrl ? `${baseUrl}/${item.imageUrl.replace(/\\/g, '/')}` : null
            }));
        }
        return res;
    }),
    getById: (id) => api.get(`/food-items/${id}`),
    toggleFavorite: (storeId, itemId) => api.post('/store-configs/toggle-favorite', { storeId, itemId }),
    getFavorites: () => api.get('/food-items', { params: { isFavorite: true } }).then(res => {
        if (res.data.isOk && res.data.data) {
            const baseUrl = BASE_URL;
            res.data.data = res.data.data.map(item => ({
                ...item,
                image: item.imageUrl ? `${baseUrl}/${item.imageUrl.replace(/\\/g, '/')}` : null
            }));
        }
        return res;
    }),
};

// Store Menu API (Store-specific configuration)
export const storeMenuAPI = {
    getMenu: (storeId) => api.get(`/store-configs/${storeId}/menu`).then(res => {
        // Transform items to include full image URLs
        if (res.data.isOk && res.data.data?.items) {
            const baseUrl = BASE_URL;
            res.data.data.items = res.data.data.items.map(item => ({
                ...item,
                image: item.imageUrl ? `${baseUrl}/${item.imageUrl.replace(/\\/g, '/')}` : null
            }));
        }
        return res;
    }),
};

// Orders API
export const ordersAPI = {
    create: (data) => api.post('/orders', data),
    getAll: (params) => api.get('/orders', { params }),
    getById: (id) => api.get(`/orders/${id}`),
    updateStatus: (id, status) => api.patch(`/orders/${id}/status`, { status }),
};

// Bills API
export const billsAPI = {
    generate: (orderId) => api.post(`/orders/${orderId}/bill`),
    getByDate: (date) => api.get('/bills', { params: { date } }),
    print: (billId) => api.get(`/bills/${billId}/print`, { responseType: 'blob' }), // Get PDF as blob
};

// KOT API
export const kotAPI = {
    generate: (orderId) => api.post(`/orders/${orderId}/kot`),
    getByDate: (date) => api.get('/kot', { params: { date } }),
    print: (kotId) => api.get(`/kot/${kotId}/print`, { responseType: 'blob' }), // Get PDF as blob
};

// Coupons API
export const couponsAPI = {
    getAll: (params) => api.get('/coupons', { params }),
    create: (data) => api.post('/coupons', data),
    update: (id, data) => api.put(`/coupons/${id}`, data),
    delete: (id) => api.delete(`/coupons/${id}`),
    validate: (data) => api.post('/coupons/validate', data)
};

// Store API
export const storeAPI = {
    getById: (id) => api.get(`/stores/${id}`),
    getConfig: (id) => api.get(`/stores/${id}/config`),
};

// Reports API
export const reportsAPI = {
    getDailyReport: (params) => api.get('/reports/daily', { params }),
    getDateRangeReport: (params) => api.get('/reports/date-range', { params }),
    getMonthlyReport: (params) => api.get('/reports/monthly', { params }),
    getProductRevenue: (params) => api.get('/reports/product-wise', { params }),
    getCategoryRevenue: (params) => api.get('/reports/category-wise', { params }),
};

export default api;
