import React from 'react';

const CategorySidebar = ({ categories, selectedCategory, onSelectCategory }) => {
    return (
        <aside className="w-24 md:w-32 bg-white dark:bg-slate-900 border-r border-slate-200 dark:border-slate-800 flex flex-col overflow-y-auto no-scrollbar shrink-0">
            <nav className="flex flex-col p-2 gap-2">
                {categories.map((category) => (
                    <button
                        key={category._id}
                        onClick={() => onSelectCategory(category)}
                        className={`flex flex-col items-center justify-center py-4 px-2 rounded-xl transition-all ${
                            selectedCategory?._id === category._id
                                ? 'bg-primary text-white shadow-lg shadow-primary/20'
                                : 'text-slate-500 hover:bg-slate-50 dark:hover:bg-slate-800'
                        }`}
                    >
                        <span className="material-icons-round mb-1">
                            {category.icon || 'category'}
                        </span>
                        <span className="text-[10px] md:text-xs font-semibold uppercase tracking-wider text-center">
                            {category.categoryName}
                        </span>
                    </button>
                ))}
            </nav>
        </aside>
    );
};

export default CategorySidebar;
